SELECT YEAR(s.opened_date) AS opened_year, DATE_FORMAT(s.opened_date, 'yyyy-MM') AS opened_month, MIN(o.order_date) AS min_order_date, MIN(o.shipping_fee) AS min_shipping_fee FROM orders o INNER JOIN stores s ON o.store_id = s.id RIGHT OUTER JOIN customers c ON o.customer_id = c.id WHERE MONTH(s.opened_date) IN (2, 10, 11) GROUP BY YEAR(s.opened_date), DATE_FORMAT(s.opened_date, 'yyyy-MM') ORDER BY opened_month DESC, 3 DESC, opened_year LIMIT 20;
